-- DAKI scoped system foundation. Additive only; does not rewrite legacy rows.
CREATE TABLE IF NOT EXISTS system_config (system_scope TEXT NOT NULL CHECK(system_scope IN ('business','bot')), config_key TEXT NOT NULL, config_value TEXT NOT NULL, updated_by TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(system_scope,config_key));
CREATE TABLE IF NOT EXISTS system_instructions (id INTEGER PRIMARY KEY AUTOINCREMENT, system_scope TEXT NOT NULL CHECK(system_scope IN ('business','bot')), instruction TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_bans (system_scope TEXT NOT NULL CHECK(system_scope IN ('business','bot')), user_id TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', blocked_by TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(system_scope,user_id));
CREATE TABLE IF NOT EXISTS system_users (system_scope TEXT NOT NULL CHECK(system_scope IN ('business','bot')), user_id TEXT NOT NULL, username TEXT, first_name TEXT, language TEXT, last_seen TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(system_scope,user_id));
CREATE TABLE IF NOT EXISTS system_groups (system_scope TEXT NOT NULL CHECK(system_scope IN ('business','bot')), chat_id TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, mode TEXT NOT NULL DEFAULT 'mention', updated_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(system_scope,chat_id));
CREATE TABLE IF NOT EXISTS system_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, system_scope TEXT NOT NULL CHECK(system_scope IN ('business','bot')), rule_type TEXT NOT NULL, rule_value TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(system_scope,rule_type,rule_value));
